/* C API of the Rust port of `intrad.c`, generated by rust-anything. */
#ifndef INTRAD_RS_H
#define INTRAD_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

double IRView(int fixed, int i, int j, int mask, double L, double W, double H, double mass, double rot);
double IRScriptF(int i, int j, int mask, double L, double W, double H, double mass, double rot, double e0, double de);
double IRFmrt(int fp, int i, int mask, double L, double W, double H, double mass, double e0, double de);

/* The same functions under `rust_anything_` names, for shadow runs. */
double rust_anything_IRView(int fixed, int i, int j, int mask, double L, double W, double H, double mass, double rot);
double rust_anything_IRScriptF(int i, int j, int mask, double L, double W, double H, double mass, double rot, double e0, double de);
double rust_anything_IRFmrt(int fp, int i, int mask, double L, double W, double H, double mass, double e0, double de);

#endif /* INTRAD_RS_H */
